#!/usr/bin/env python3
"""Bake web/index.html into tray/webapp.h (gzipped) so the tray Arduino can serve it.

Run this after every change to web/index.html, then re-upload the sketch:
    python3 tools/embed_web.py
"""
import gzip
from pathlib import Path

root = Path(__file__).resolve().parent.parent
html = (root / "web" / "index.html").read_bytes()
gz = gzip.compress(html, compresslevel=9, mtime=0)

rows = [", ".join(f"0x{b:02x}" for b in gz[i : i + 16]) for i in range(0, len(gz), 16)]
header = (
    "// Generated by tools/embed_web.py from web/index.html. Do not edit by hand:\n"
    "// change web/index.html and run `python3 tools/embed_web.py` again.\n"
    "#pragma once\n#include <stddef.h>\n#include <stdint.h>\n\n"
    f"const size_t WEBAPP_GZ_LEN = {len(gz)};\n"
    "const uint8_t WEBAPP_GZ[] = {\n  " + ",\n  ".join(rows) + "\n};\n"
)
(root / "tray" / "webapp.h").write_text(header)
print(f"web/index.html {len(html):,} bytes -> tray/webapp.h ({len(gz):,} bytes gzipped)")
